#include <iostream>
using namespace std;

int main() {
    char board[4][4];

    for (int i = 0; i < 4; ++i)
        for (int j = 0; j < 4; ++j)
            cin >> board[i][j];

    const int directions[4][2] = {
        {0, 1}, {1, 0}, {1, 1}, {1, -1}
    };

    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            for (const auto& direction : directions) {
                int xCount = 0;
                bool valid = true;

                for (int k = 0; k < 3; ++k) {
                    int row = i + k * direction[0];
                    int col = j + k * direction[1];

                    if (row < 0 || row >= 4 || col < 0 || col >= 4) {
                        valid = false;
                        break;
                    }

                    if (board[row][col] == 'x')
                        ++xCount;
                    else if (board[row][col] != '.')
                        valid = false;
                }

                if (valid && xCount >= 2) {
                    cout << "YES";
                    return 0;
                }
            }
        }
    }

    cout << "NO";
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    char board[4][4];

    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            cin >> board[i][j];
        }
    }

    const int directions[4][2] = {
        {0, 1}, {1, 0}, {1, 1}, {1, -1}
    };

    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            for (const auto& direction : directions) {
                int endRow = i + 2 * direction[0];
                int endCol = j + 2 * direction[1];

                if (endRow < 0 || endRow >= 4 || endCol < 0 || endCol >= 4) {
                    continue;
                }

                int xCount = 0;
                int dotCount = 0;

                for (int k = 0; k < 3; ++k) {
                    char cell = board[i + k * direction[0]]
                                     [j + k * direction[1]];
                    xCount += (cell == 'x');
                    dotCount += (cell == '.');
                }

                if (xCount == 2 && dotCount == 1) {
                    cout << "YES";
                    return 0;
                }
            }
        }
    }

    cout << "NO";
    return 0;
}

